%[text] # Motor Drive Unit - Simulation Case
%[text] ## Randomly generated input signals
%[text] Test that the model runs with reasonably random inputs. This is part of stress-test.
mdl = "MotorDriveUnit_TestModel";
load_system(mdl)
MotorDriveUnit_TestModelSetup
%[text] Select model to use.
MotorDriveUnit_setRefsub_BasicThermal %[output:68dc68f2]
%[text] Load simulation case.
MotorDriveUnit_setSimCase_Random %[output:684d78f0]
%[text] Run simulation.
simOut = sim(mdl);
%[text] Visually inspect the result.
simData = extractTimetable(simOut.logsout);
sigNames = [
  "Motor torque command"
  "Axle torque input"
  "Motor power rate"
  "Motor speed"
  "Motor temperature"
  "Battery power"
  "Battery current"
  "Battery voltage"
  ];
for i = 1 : numel(sigNames) %[output:group:75a624df]
  TimetableSingleSignalPlot( ... %[output:90e913da] %[output:4d7245f3] %[output:23ff8f46] %[output:5a653a93] %[output:7a9be45d] %[output:93d4f873] %[output:3dd555d9] %[output:7a49bdf6]
    Timetable = simData, ... %[output:90e913da] %[output:4d7245f3] %[output:23ff8f46] %[output:5a653a93] %[output:7a9be45d] %[output:93d4f873] %[output:3dd555d9] %[output:7a49bdf6]
    SignalName = sigNames(i), ... %[output:90e913da] %[output:4d7245f3] %[output:23ff8f46] %[output:5a653a93] %[output:7a9be45d] %[output:93d4f873] %[output:3dd555d9] %[output:7a49bdf6]
    PlotHeight = 200 ); %[output:90e913da] %[output:4d7245f3] %[output:23ff8f46] %[output:5a653a93] %[output:7a9be45d] %[output:93d4f873] %[output:3dd555d9] %[output:7a49bdf6]
end %[output:group:75a624df]
